//! # The verdict core (TF01 §3)
//!
//! Two pure functions decide whether a test passed. They never panic,
//! never print and never read configuration, so the same inputs always give
//! the same verdict, and the corpus can pin every one of them.
//!
//! Only two, because those are all `ct-compare`'s conformance needs. Richer
//! assertions are generated by Warrant (VER04) on top of these.

use crate::tfv::{encode, values_equal, Value};

/// The outcome of a check.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Verdict {
    Pass,
    /// `failure_id` is from a closed vocabulary (TF01 §5.3) so tools can
    /// group failures; `message` is for people.
    Fail {
        failure_id: &'static str,
        message: String,
    },
}

impl Verdict {
    /// A failure with the given id and message.
    pub fn fail(failure_id: &'static str, message: impl Into<String>) -> Verdict {
        Verdict::Fail {
            failure_id,
            message: message.into(),
        }
    }
}

/// The complete TF01 section 5.3 failure vocabulary.
///
/// This is a protocol predicate, not an assertion about a subject. The runner
/// applies it when serializing, so callers cannot bypass it by constructing
/// the public `Fail` variant instead of using the convenience constructor.
pub fn is_registered_failure_id(id: &str) -> bool {
    matches!(
        id,
        "not-deep-equal"
            | "no-error"
            | "wrong-error"
            | "panic"
            | "corpus-mismatch"
            | "corpus-malformed"
            | "property-counterexample"
            | "property-exhausted"
            | "property-timeout"
            | "property-panic"
    )
}

/// `Pass` when `actual` and `expected` are deep-equal, else
/// `Fail("not-deep-equal")`.
///
/// ```text
///   deep_equal(I5, I5)                        → Pass
///   deep_equal(D7ff8000000000000, D7ff0000000000001)  → Pass (NaN = NaN)
///   deep_equal(D8000000000000000, D0000000000000000)  → Fail (-0 ≠ +0)
///   deep_equal(X61, S61)                      → Fail (bytes are not text)
/// ```
pub fn deep_equal(actual: &Value, expected: &Value) -> Verdict {
    if values_equal(actual, expected) {
        Verdict::Pass
    } else {
        Verdict::fail(
            "not-deep-equal",
            format!("expected {}, got {}", encode(expected), encode(actual)),
        )
    }
}

/// Did the code under test raise the expected error?
///
/// `raised` is `None` when nothing was raised, or the semantic error id
/// that was.
///
/// | raised            | verdict              |
/// |-------------------|----------------------|
/// | `None`            | `Fail("no-error")`   |
/// | another id        | `Fail("wrong-error")`|
/// | `expected_id`     | `Pass`               |
pub fn error_is(raised: Option<&str>, expected_id: &str) -> Verdict {
    match raised {
        None => Verdict::fail(
            "no-error",
            format!("expected error {expected_id:?}, none raised"),
        ),
        Some(id) if id == expected_id => Verdict::Pass,
        Some(id) => Verdict::fail(
            "wrong-error",
            format!("expected error {expected_id:?}, got {id:?}"),
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn messages_use_tfv_notation() {
        let verdict = deep_equal(&Value::Bool(false), &Value::Bool(true));
        assert_eq!(
            verdict,
            Verdict::fail("not-deep-equal", "expected T, got F")
        );
    }

    #[test]
    fn error_messages_name_both_ids() {
        assert_eq!(
            error_is(Some("B"), "A"),
            Verdict::fail("wrong-error", "expected error \"A\", got \"B\"")
        );
        assert_eq!(
            error_is(None, "A"),
            Verdict::fail("no-error", "expected error \"A\", none raised")
        );
    }
}
